const dot = (a, b) =>
  a.reduce((sum, x, i) => sum + x * b[i], 0);
const norm = (a) => Math.sqrt(dot(a, a));

const cosine = (a, b) => dot(a, b) / (norm(a) * norm(b));

cosine([1, 2], [2, 4]);  // 1: same direction
cosine([1, 0], [0, 1]);  // 0: right angle
cosine([1, 0], [-1, 0]); // -1: opposite

CREATE EXTENSION vector;

CREATE TABLE chunks (
  id bigserial PRIMARY KEY,
  body text,
  embedding vector(1536)
);

-- the 5 chunks nearest to the query vector $1
SELECT id, body, embedding <=> $1 AS distance
FROM chunks
ORDER BY embedding <=> $1
LIMIT 5;

const normalise = (v) => {
  const length = Math.hypot(...v);
  return length === 0 ? v : v.map((x) => x / length);
};

const dot = (a, b) =>
  a.reduce((sum, x, i) => sum + x * b[i], 0);

const a = normalise([3, 4]);  // [0.6, 0.8]
const b = normalise([4, 3]);  // [0.8, 0.6]
dot(a, b);                    // 0.96 = cosine

